type OfferData={id:number;title:string;description:string;category:string;discount_type:string;discount_value:number;maximum_discount?:number;minimum_fare:number;promo_code:string;start_at:string;expires_at:string;status:string;usage_limit?:number;per_user_limit:number;eligibility:string;terms:string;routes:{origin:string;destination:string}[];airlines:string[];cabins:string[];redemptions:number;remaining?:number};
const offerDiscountLabel=(o:OfferData)=>o.discount_type==='FIXED_AMOUNT'?`₹${o.discount_value.toLocaleString('en-IN')} OFF`:`${o.discount_value}% OFF`;
function OfferCountdown({date,status}:{date:string;status:string}){const[left,setLeft]=useState('');useEffect(()=>{const tick=()=>{const ms=Date.parse(date)-Date.now();if(ms<=0)setLeft('EXPIRED');else{const d=Math.floor(ms/86400000),h=Math.floor(ms%86400000/3600000),m=Math.floor(ms%3600000/60000);setLeft(`${d}d ${h}h ${m}m`)}};tick();const t=setInterval(tick,60000);return()=>clearInterval(t)},[date]);return <span className="offerCountdown"><small>{status==='ACTIVE'?'ENDS IN':'STATUS'}</small><b>{status==='ACTIVE'?left:status}</b></span>}
